<?php
/**
 * Student access codes: generated by an administrator, given to the student,
 * and stored only as a bcrypt hash (like a password).
 *
 * Plain PHP (unit-tested without WordPress).
 */

defined( 'ABSPATH' ) || exit;

final class URP_Access_Codes {

	/** No 0/O, 1/I/L so codes are easy to read aloud and type. 31^10 ≈ 8×10^14 combinations. */
	const ALPHABET = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
	const LENGTH   = 10;
	const COST     = 11;

	/** Hash of a value that is never a valid code; used so unknown students take as long to check as known ones. */
	const DUMMY_HASH = '$2y$11$9ot0vOUy3Qq25y7Yuo8wb.We8tTYEVtWOa2qRxWEI10c6CXzwJ1ji';

	/** @return string e.g. "K7QM2-XH9TP" */
	public static function generate(): string {
		$code = '';
		$max  = strlen( self::ALPHABET ) - 1;
		for ( $i = 0; $i < self::LENGTH; $i++ ) {
			$code .= self::ALPHABET[ random_int( 0, $max ) ];
		}
		return substr( $code, 0, 5 ) . '-' . substr( $code, 5 );
	}

	/** Accepts lower case, spaces and dashes the way students tend to type them. */
	public static function normalize( string $code ): string {
		return strtoupper( (string) preg_replace( '/[^A-Za-z0-9]/', '', $code ) );
	}

	public static function hash( string $code ): string {
		return password_hash( self::normalize( $code ), PASSWORD_BCRYPT, array( 'cost' => self::COST ) );
	}

	/**
	 * @param string|null $hash The student's stored hash, or null when the student doesn't exist / has no code.
	 */
	public static function verify( string $code, ?string $hash ): bool {
		$normalized = self::normalize( $code );
		// Always run one bcrypt check so response time doesn't reveal whether the student exists.
		$matches = password_verify( $normalized, $hash ? $hash : self::DUMMY_HASH );
		return $matches && null !== $hash && '' !== $hash && self::LENGTH === strlen( $normalized );
	}
}
